import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DXYAzton.js";var i=JSON.parse(`{"title":"2022 – 2023 School Year","description":"","frontmatter":{},"headers":[],"relativePath":"projects/2022.md","filePath":"projects/2022.md","lastUpdated":1785289364000}`),a={name:`projects/2022.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="_2022-–-2023-school-year" tabindex="-1">2022 – <em>2023 School Year</em> <a class="header-anchor" href="#_2022-–-2023-school-year" aria-label="Permalink to “2022 – 2023 School Year”">​</a></h1><h2 id="fall-semester" tabindex="-1">Fall Semester <a class="header-anchor" href="#fall-semester" aria-label="Permalink to “Fall Semester”">​</a></h2><h3 id="paul-mcglothlin" tabindex="-1">Paul McGlothlin <a class="header-anchor" href="#paul-mcglothlin" aria-label="Permalink to “Paul McGlothlin”">​</a></h3><h3 id="patrick-snow" tabindex="-1">Patrick Snow <a class="header-anchor" href="#patrick-snow" aria-label="Permalink to “Patrick Snow”">​</a></h3><ul><li><strong>Project Advisor</strong>: Dr. Sean T. Hayes</li><li><strong>Abstract</strong>: The website will provide several personality quizzes on the home page. In order for the user to access the home page they will be required to either create a new account or simply sign in with an existing account that is already made and stored on the website&#39;s storage database. Once, the user logs in then they can pick any of the quizzes that are provided. The quizzes that are provided will have a set of questions that will be required for the user to answer to get a better understanding of their personality. After the user submits their answer they will then be taken to a result page that will show what character, icon, music, artist, ect. that share similarities to their personality. If the user is satisfied with their result then they can share the URL with their result and/or choose to save their result to their account/profile. The navigation bar will be the same throughout any page browsed through the website in which it will have the website logo, title, profile page link, and a sign out button. The logo and website title is a clickable link for the user that will take them to the homepage. The home page will also provide two buttons called Create and Browse which will take the user to separate pages.</li><li><a href="https://github.com/soccerguy820/CSU-Senior-Project" target="_blank" rel="noreferrer">Source Code Repository</a></li></ul><h3 id="steven-yeung-–-four-part-harmony-rule-checker-extension-for-musescore" tabindex="-1">Steven Yeung – <em>Four-Part Harmony Rule Checker Extension for Musescore</em> <a class="header-anchor" href="#steven-yeung-–-four-part-harmony-rule-checker-extension-for-musescore" aria-label="Permalink to “Steven Yeung – Four-Part Harmony Rule Checker Extension for Musescore”">​</a></h3><ul><li><strong>Project Advisor</strong>: Dr. Sean T. Hayes</li><li><strong>Abstract</strong>: The four-part writing machine project is a plugin that recreates the rules of four-part harmony visually. It does this by implementing logic that takes tonal pitch classes, note pitch values, whole, and half steps to determine what rules have been broken in a user’s four-part harmony.</li><li><a href="https://github.com/yeungs2019/CSU-Senior-Project" target="_blank" rel="noreferrer">Source Code Repository</a></li></ul><h2 id="spring-semester" tabindex="-1">Spring Semester <a class="header-anchor" href="#spring-semester" aria-label="Permalink to “Spring Semester”">​</a></h2><h3 id="christopher-austin-hicks" tabindex="-1">Christopher Austin Hicks <a class="header-anchor" href="#christopher-austin-hicks" aria-label="Permalink to “Christopher Austin Hicks”">​</a></h3><h3 id="joseph-andrew-kaufman" tabindex="-1">Joseph Andrew Kaufman <a class="header-anchor" href="#joseph-andrew-kaufman" aria-label="Permalink to “Joseph Andrew Kaufman”">​</a></h3><h3 id="ji-sun-min" tabindex="-1">Ji Sun Min <a class="header-anchor" href="#ji-sun-min" aria-label="Permalink to “Ji Sun Min”">​</a></h3><h3 id="carter-thomas-hinkle" tabindex="-1">Carter Thomas Hinkle <a class="header-anchor" href="#carter-thomas-hinkle" aria-label="Permalink to “Carter Thomas Hinkle”">​</a></h3><h3 id="christian-thomas-hinkle" tabindex="-1">Christian Thomas Hinkle <a class="header-anchor" href="#christian-thomas-hinkle" aria-label="Permalink to “Christian Thomas Hinkle”">​</a></h3><h3 id="scott-christopher-koenig-ii-–-godot-menu-system" tabindex="-1">Scott Christopher Koenig, II – <em>Godot Menu System</em> <a class="header-anchor" href="#scott-christopher-koenig-ii-–-godot-menu-system" aria-label="Permalink to “Scott Christopher Koenig, II – Godot Menu System”">​</a></h3><ul><li><strong>Project Advisor</strong>: Dr. Sean T. Hayes</li></ul><h3 id="myles-patrick-o-toole" tabindex="-1">Myles Patrick O&#39;Toole <a class="header-anchor" href="#myles-patrick-o-toole" aria-label="Permalink to “Myles Patrick O&#39;Toole”">​</a></h3><ul><li><strong>Project Advisor</strong>: Dr. Sean T. Hayes</li></ul><h3 id="micah-daniel-stargel-–-eagle-eye-scavenger-hunts" tabindex="-1">Micah Daniel Stargel – <em>Eagle Eye Scavenger Hunts</em> <a class="header-anchor" href="#micah-daniel-stargel-–-eagle-eye-scavenger-hunts" aria-label="Permalink to “Micah Daniel Stargel – Eagle Eye Scavenger Hunts”">​</a></h3><ul><li><strong>Project Advisor</strong>: Dr. Sean T. Hayes</li><li><strong>Abstract</strong>: Eagle Eye Scavenger Hunts is a web- and GPS-based application that enables users to create, manage, and participate in customizable scavenger hunts without the need to place physical clues. The project addresses limitations of existing scavenger hunt platforms, which often require paid subscriptions or provide only pre-built experiences. By allowing organizers to define virtual clues that become available based on a participant&#39;s geographic location, the application provides an accessible, flexible, and engaging platform for recreation, team building, education, and community events. The system emphasizes ease of use, customization, and affordability while leveraging modern web technologies and location-aware services to deliver an interactive scavenger hunt experience.</li><li><a href="https://github.com/mdstargel/CSU-Senior-Project-2023" target="_blank" rel="noreferrer">Source Code Repository</a></li><li><a href="https://github.com/mdstargel/CSU-Senior-Project-2023/tree/main/docs" target="_blank" rel="noreferrer">Documentation</a></li></ul><h3 id="kilik-rashard-white-–-programming-versus" tabindex="-1">Kilik Rashard White – <strong>Programming Versus</strong> <a class="header-anchor" href="#kilik-rashard-white-–-programming-versus" aria-label="Permalink to “Kilik Rashard White – Programming Versus”">​</a></h3><ul><li><p><strong>Project Advisor</strong>: Dr. Sean T. Hayes</p></li><li><p><strong>Abstract</strong>: Programming competitions are a major event for computer programmers to show off their practiced skills. There are many practice methods for one person, which are available everywhere. However, the process of training for programming competitions is tough without another person to directly help to practice. Fortunately, group practice for programming competitions can be done with this program along with general practice.</p><p>The program functions similarly to a program called HackerRank. Where it differs is that the program adds a shared experience with other people through an online component. Because of the online component, this program will allow multiple students to practice against other people to hone their programming skills for programming competitions and make group practice more possible. It will also generate a lot more interest in programmers because of the spectator aspect of the program. It will lead to more programmers that are not interested in the programming competitions becoming either more interested in competitions because of the game aspect or become more skilled at programming. Overall, the program will fix the issue of poor group practice avenues and allow programmers a new avenue to practice in groups for programming competitions.</p></li><li><p><a href="https://github.com/kilikwhite/CSU-Senior-Project" target="_blank" rel="noreferrer">Source Code Repository</a></p></li><li><p><a href="https://github.com/kilikwhite/CSU-Senior-Project/tree/master/docs/Defence_Docs" target="_blank" rel="noreferrer">Documentation</a></p></li></ul>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};